            t=c if isinstance(c,str) else "\n".join(b.get('text','') for b in c if isinstance(b,dict)) if isinstance(c,list) else ''
            if t and 'final_answer' in t:
                import re
                mm=re.search(r'"final_answer"\s*:\s*"((?:[^"\\]|\\.)*)"',t)
                if mm:
                    try: final=json.loads('"'+mm.group(1)+'"')
                    except Exception: final=mm.group(1)
