def _shape_line(self, parts: int, question: str = "") -> tuple[str, bool, bool]:
    """How the references render their answer, for this question in particular.

    Returns ``(line, mismatch, defect)``. When the question states a header the
    references share, the count comes from that family alone, because that is the
    only evidence that describes this question rather than the corpus; the corpus
    line is the fallback and never decides anything, since a spread that mixes
    question types is a discrepancy on nearly every draft.

    A family that answers with one count in almost every case contradicts a draft
    with another count, and that contradiction is a rendering defect: the whole
    point of the line is that the count here is not a matter of taste.
    """
    widths = {int(width): count for width, count in (self.profile.get("part_widths") or {}).items()}
    family = self.family(question)
    family_widths = {
        int(width): count for width, count in ((family or {}).get("widths") or {}).items()
    }
    if family_widths:
        total = sum(family_widths.values()) or 1
        spread = ", ".join(
            f"{width} part{'s' if width != 1 else ''} in {round(100 * count / total)}%"
            for width, count in sorted(family_widths.items())
        )
        mode, mode_count = max(family_widths.items(), key=lambda item: (item[1], -item[0]))
        line = (
            f"- Shape: your answer has {parts} part(s); the {total} reference case(s) of this"
            f" question's own type answer with {spread}."
        )
        if parts != mode:
            share = round(100 * mode_count / total)
            line += (
                f" This type answers with {mode} part{'s' if mode != 1 else ''} in {share}% of its"
                " cases, so check the count against the facts: the parts an answer of this type"
                " carries are the ones the facts establish, and an answer with a different count"
                " is a different answer."
            )
        return line, parts != mode, parts != mode and mode_count / total >= FAMILY_SHAPE_SHARE
    if not widths:
        return "", False, False
    low, high = min(widths), max(widths)
    if low == high:
        line = (
            f"- Shape: your answer has {parts} part(s); every reference answer has {low} part(s)."
        )
        return line, parts != low, False
    return (
        f"- Shape: your answer has {parts} part(s); reference answers run from {low} to {high}"
        " parts, and no single count is the rule across the references.",
        False,
        False,
    )

